{
  "name": "bugxhunter",
  "version": "0.9.6",
  "description": "BugXHunter: an AI security-testing agent with a sandboxed runner, a passkey-sealed key vault and read-only GitHub access. `npx bugxhunter` runs it on your machine.",
  "license": "MIT",
  "homepage": "https://bugxhunter.com",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/cintelis/bugxhunter-runner.git"
  },
  "bugs": {
    "url": "https://github.com/cintelis/bugxhunter-runner/issues"
  },
  "keywords": [
    "security",
    "pentest",
    "bug-bounty",
    "ai-agent",
    "opencode",
    "vulnerability-scanner",
    "code-review"
  ],
  "type": "module",
  "bin": {
    "bugxhunter": "bin/bugxhunter.mjs"
  },
  "engines": {
    "node": ">=22"
  },
  "dependencies": {
    "@anthropic-ai/sdk": "^1.3.0",
    "@opencode-ai/sdk": "^1.17.11",
    "dotenv": "^18.0.6",
    "express": "^5.2.1",
    "express-rate-limit": "^8.7.1",
    "opencode-ai": "^1.18.35"
  },
  "publishConfig": {
    "access": "public"
  }
}

#!/usr/bin/env node
/**
 * The `bugxhunter` command (npx bugxhunter / npm i -g bugxhunter).
 *
 *   bugxhunter                      run the runner here, UI on http://localhost:8790
 *   bugxhunter [--port N] [--dir P] [--no-open]
 *   bugxhunter docker [--slim|--full] the sandboxed stack: writes ~/.config/bugxhunter/docker
 *                                   (compose file + .env secrets), pulls the signed images
 *                                   matching this version, starts it, opens the UI.
 *                                   With args, runs `docker compose <args>` there (down, logs…).
 *   bugxhunter docker export <path> [dest]  copy a file or folder out of /workspace (a Docker volume
 *                                   Finder cannot open) into dest, default: here
 *   bugxhunter vault reset           break-glass: delete the key vault (see scripts/vault-reset.mjs)
 *
 * Local mode runs the agent on this machine: OpenCode is a dependency of this
 * package, so nothing else needs installing. Its binary is found by putting
 * this package's node_modules/.bin on PATH before the server starts.
 */
import { spawn, spawnSync } from "node:child_process";
import crypto from "node:crypto";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const pkg = JSON.parse(fs.readFileSync(path.join(ROOT, "package.json"), "utf8"));
const CONFIG_DIR = path.join(os.homedir(), ".config", "bugxhunter");

const args = process.argv.slice(2);
const flag = (name) => { const i = args.indexOf(name); return i >= 0 ? (args.splice(i, 1), true) : false; };
const opt = (name) => { const i = args.indexOf(name); if (i < 0) return undefined; const v = args[i + 1]; args.splice(i, 2); return v; };

if (flag("--version") || flag("-v")) { console.log(pkg.version); process.exit(0); }
if (flag("--help") || flag("-h")) {
  console.log(`bugxhunter ${pkg.version}

  bugxhunter                       run the runner here (agent on this machine), UI on http://localhost:8790
    --port <n>                     UI port (default 8790, or PORT)
    --dir <path>                   default project folder (default: the current folder)
    --no-open                      don't open the browser
  bugxhunter docker                the sandboxed stack via Docker (writes ~/.config/bugxhunter/docker, pulls the
                                   signed images for v${pkg.version}, starts, opens the UI)
    --slim                         the agent image without the scan toolchain: half the download, code review only
    --full                         back to the full image (the default)
  bugxhunter docker <args>         docker compose <args> in that folder, e.g. down, logs -f, ps
  bugxhunter docker export <path> [dest]
                                   copy a file or folder out of /workspace into dest (default: here);
                                   <path> may be absolute (/workspace/acme/app/report.md) or relative to /workspace
  bugxhunter vault reset           delete the key vault when every unlock factor is lost

Docs: https://github.com/cintelis/bugxhunter-runner`);
  process.exit(0);
}

const cmd = args[0];
if (cmd === "docker") await dockerMode(args.slice(1));
else if (cmd === "vault" && args[1] === "reset") await vaultReset(args.slice(2));
else if (cmd && !cmd.startsWith("-")) { console.error(`unknown command: ${cmd} (try --help)`); process.exit(2); }
else await localMode();

// --- local mode -----------------------------------------------------------------------

async function localMode() {
  const port = Number(opt("--port") ?? process.env.PORT ?? 8790);
  const dir = path.resolve(opt("--dir") ?? process.env.OPEN_RUNNER_DIR ?? process.cwd());
  const open = !flag("--no-open");

  // Settings: ~/.config/bugxhunter/.env, then ./.env (both optional; never printed).
  const { default: dotenv } = await import("dotenv");
  for (const f of [path.join(CONFIG_DIR, ".env"), path.join(process.cwd(), ".env")]) {
    if (fs.existsSync(f)) dotenv.config({ path: f });
  }
  process.env.NODE_ENV ??= "production";
  process.env.PORT = String(port);
  process.env.OPEN_RUNNER_DIR = dir;

  // OpenCode's binary lives in this package's dependencies.
  const bins = [path.join(ROOT, "node_modules", ".bin"), path.resolve(ROOT, "..", ".bin")];
  process.env.PATH = [...bins.filter((b) => fs.existsSync(b)), process.env.PATH ?? ""].join(path.delimiter);
  if (!hasOpencode()) {
    console.error("OpenCode was not found. It is installed with this package; try `npm i -g bugxhunter` again, or `npm i -g opencode-ai`.");
    process.exit(1);
  }

  const major = Number(process.versions.node.split(".")[0]);
  if (major < 22) { console.error(`Node ${process.versions.node} is too old: BugXHunter needs Node 22+.`); process.exit(1); }

  await import(pathToFileURL(path.join(ROOT, "server", "dist", "index.js")).href);
  if (open) {
    const url = `http://localhost:${port}`;
    if (await waitFor(`http://127.0.0.1:${port}/api/health`, 15_000)) openBrowser(url);
  }
}

/** Is `opencode` on PATH? A file check, since Windows .cmd shims cannot be spawned without a shell. */
function hasOpencode() {
  const names = process.platform === "win32" ? ["opencode.cmd", "opencode.exe", "opencode"] : ["opencode"];
  return (process.env.PATH ?? "").split(path.delimiter).some((d) => d && names.some((n) => fs.existsSync(path.join(d, n))));
}

async function waitFor(url, ms) {
  const until = Date.now() + ms;
  while (Date.now() < until) {
    try { const r = await fetch(url, { signal: AbortSignal.timeout(1000) }); if (r.ok) return true; } catch { /* not yet */ }
    await new Promise((r) => setTimeout(r, 250));
  }
  return false;
}

function openBrowser(url) {
  const [bin, a] = process.platform === "win32" ? ["cmd", ["/c", "start", "", url]]
    : process.platform === "darwin" ? ["open", [url]] : ["xdg-open", [url]];
  try { spawn(bin, a, { stdio: "ignore", detached: true }).unref(); } catch { /* headless: the URL is printed by the server */ }
}

// --- docker mode ----------------------------------------------------------------------

async function dockerMode(rest) {
  const slim = flag("--slim"), full = flag("--full");
  rest = rest.filter((a) => a !== "--slim" && a !== "--full");
  const dir = path.join(CONFIG_DIR, "docker");
  if (spawnSync("docker", ["compose", "version"], { stdio: "ignore" }).error) {
    console.error("Docker is not installed or not running. Install Docker Desktop (https://docs.docker.com/get-docker/) and try again.");
    process.exit(1);
  }
  fs.mkdirSync(dir, { recursive: true });
  // The compose file of this version, verbatim: the images it names are the
  // signed release images; BXH_VERSION in .env pins them to this version.
  fs.copyFileSync(path.join(ROOT, "docker-compose.yml"), path.join(dir, "docker-compose.yml"));
  const envFile = path.join(dir, ".env");
  const vals = new Map();
  let envText = "";
  try { envText = fs.readFileSync(envFile, "utf8"); } catch (e) { if (e.code !== "ENOENT") throw e; }
  for (const line of envText.split(/\r?\n/)) {
    const m = /^\s*([A-Z0-9_]+)=(.*)$/.exec(line);
    if (m) vals.set(m[1], m[2]);
  }
  const fresh = !vals.size;
  if (!vals.get("OPEN_RUNNER_SECRET")) vals.set("OPEN_RUNNER_SECRET", crypto.randomBytes(32).toString("base64url"));
  if (!vals.get("SCX_PROXY_TOKEN")) vals.set("SCX_PROXY_TOKEN", crypto.randomBytes(32).toString("base64url"));
  vals.set("BXH_VERSION", `v${pkg.version}`);
  // The agent flavour sticks until changed: `--slim` once, then plain `docker` keeps it.
  if (slim) vals.set("BXH_AGENT_FLAVOR", "-slim");
  if (full) vals.delete("BXH_AGENT_FLAVOR");
  const flavor = vals.get("BXH_AGENT_FLAVOR") ?? "";
  fs.writeFileSync(envFile, [...vals].map(([k, v]) => `${k}=${v}`).join("\n") + "\n", { mode: 0o600 });
  console.log(`${fresh ? "Created" : "Updated"} ${dir} (compose file + .env; secrets are random and never printed)`);

  const compose = (a) => spawnSync("docker", ["compose", ...a], { cwd: dir, stdio: "inherit" }).status ?? 1;
  if (rest[0] === "export") {
    const src = rest[1];
    if (!src) { console.error("usage: bugxhunter docker export <path-in-workspace> [dest]"); process.exit(2); }
    const inside = src.startsWith("/") ? path.posix.normalize(src) : path.posix.join("/workspace", src);
    if (!inside.startsWith("/workspace/")) { console.error("the path must be inside /workspace"); process.exit(2); }
    const dest = path.resolve(rest[2] ?? path.posix.basename(inside));
    const code = compose(["cp", `agent:${inside}`, dest]);
    if (code === 0) console.log(`copied ${inside} → ${dest}`);
    process.exit(code);
  }
  if (rest.length) process.exit(compose(rest));
  console.log(`Pulling the signed images for v${pkg.version}${flavor ? " (slim agent: no scan toolchain)" : " (the agent image is large the first time; --slim halves it)"}…`);
  if (compose(["pull"]) !== 0) process.exit(1);
  if (compose(["up", "-d"]) !== 0) process.exit(1);
  const port = vals.get("OPEN_RUNNER_PORT") ?? "8790";
  const url = `http://localhost:${port}`;
  console.log(`BugXHunter is starting at ${url}. Set up the vault in the sidebar, add your model key, connect GitHub.`);
  console.log(`Later: bugxhunter docker logs -f · bugxhunter docker down · re-run after \`npm i -g bugxhunter@latest\` to upgrade.`);
  if (await waitFor(`http://127.0.0.1:${port}/api/health`, 60_000)) openBrowser(url);
}

// --- vault reset ----------------------------------------------------------------------

async function vaultReset(rest) {
  const r = spawnSync(process.execPath, [path.join(ROOT, "scripts", "vault-reset.mjs"), ...rest], { stdio: "inherit" });
  process.exit(r.status ?? 1);
}

/**
 * BugXHunter backend.
 *
 * A thin Express server in front of OpenCode (the coding agent) and the SCX
 * platform (the playground chat). The SCX API key stays server-side; the
 * browser only ever talks to this server. Streams are forwarded as
 * Server-Sent Events.
 */
import "./env.js"; // first: loads .env before the modules below read process.env
import express from "express";
import fs from "node:fs";
import path from "node:path";
import { SCXError } from "./scx.js";
import { PROVIDERS, PROXY_TOKEN, PORT, OPENROUTER_MODELS, apiKey, clients, clientFor, isRetiredStatus, keySource, listModels, proxyPaths, proxyTokenOk, upstreamHeaders, } from "./providers.js";
import { KnowledgeBase, buildContextBlock } from "./rag.js";
import { getClient, serverUrl, resolveDirectory, projectFile, listAgentModels, toUiEvent, toUiMessages, parseModelId, oc, query, httpError, SessionFamily, childSessions, markInterrupted, DEFAULT_DIRECTORY, DEFAULT_MODEL, REMOTE_URL, REPO_ROOT, ALLOWED_ROOTS, } from "./opencode.js";
import { mountAuth, authRequired, issueSession } from "./auth.js";
import { audit, followOpencode, LOG_DIR } from "./audit.js";
import { saveAttachments } from "./attachments.js";
import * as vault from "./vault.js";
import * as playground from "./playground-store.js";
import * as nvidiaHealth from "./nvidia-health.js";
import * as render from "./render.js";
import { VERSION } from "./version.js";
import { apiLimiter, fileLimiter, staticLimiter } from "./ratelimit.js";
import { createWorkspace, deleteWorkspace, listFiles, listWorkspaces, saveUpload, WORKSPACES_ROOT } from "./workspaces.js";
import * as github from "./github.js";
// Keys, the proxy token and the provider clients live in providers.ts, which
// also scrubs every secret from the environment before OpenCode is spawned.
const scx = clients.scx;
const kb = new KnowledgeBase(scx); // in-memory RAG store (POC scope)
const app = express();
app.disable("x-powered-by");
// Behind a reverse proxy, trust its X-Forwarded-* headers so req.ip is the
// real client (the login rate limit is per IP) and req.secure sees HTTPS.
// Express accepts a hop count ("1"), "loopback", a CIDR list, or true/false.
const TRUST_PROXY = process.env.TRUST_PROXY;
if (TRUST_PROXY) {
    app.set("trust proxy", /^\d+$/.test(TRUST_PROXY) ? Number(TRUST_PROXY) : TRUST_PROXY === "true" ? true : TRUST_PROXY);
}
/**
 * Key-injecting proxy for the agent, one route per provider (/scx/v1,
 * /openrouter/v1, /nvidia/v1, /anthropic/v1). The agent's OpenCode talks to
 * these with the proxy token, and we forward model calls upstream with the real
 * key. So no provider key ever enters the container (or, locally, the process)
 * the agent's shell runs in. Mounted before the JSON parser so request bodies
 * pass through untouched. Anthropic's API takes its key in `x-api-key`, so the
 * proxy token arrives there too for that route (see proxyTokenOk).
 */
for (const p of Object.values(PROVIDERS)) {
    const prefix = `/${p.id}/v1`;
    app.all(`${prefix}/*path`, async (req, res) => {
        const sub = req.path.slice(prefix.length);
        if (!proxyTokenOk(p, req.headers, PROXY_TOKEN))
            return res.status(401).json({ error: { message: "bad proxy token" } });
        if (!proxyPaths(p).has(sub))
            return res.status(404).json({ error: { message: `not proxied: ${sub}` } });
        try {
            const chunks = [];
            for await (const c of req)
                chunks.push(c);
            const ctrl = new AbortController();
            res.on("close", () => ctrl.abort());
            const upstream = await fetch(p.baseUrl + sub + (req.url.includes("?") ? req.url.slice(req.url.indexOf("?")) : ""), {
                method: req.method,
                headers: upstreamHeaders(p, req.headers, apiKey(p.id)),
                body: req.method === "GET" || req.method === "HEAD" ? undefined : Buffer.concat(chunks),
                signal: ctrl.signal,
            });
            res.status(upstream.status);
            const type = upstream.headers.get("content-type");
            if (type)
                res.setHeader("Content-Type", type);
            if (!upstream.body)
                return res.end();
            for await (const chunk of upstream.body)
                res.write(chunk);
            res.end();
        }
        catch (e) {
            if (!res.headersSent)
                res.status(e.status ?? 502).json({ error: { message: String(e.message ?? e) } });
            else
                res.end();
        }
    });
}
/**
 * DNS-rebinding guard. A malicious page can point a hostname it controls at
 * 127.0.0.1 and then call this API from the victim's browser; the Host header
 * still names the attacker's domain, so refuse anything but our own names.
 * Add the names a reverse proxy serves under via ALLOWED_HOSTS.
 */
const ALLOWED_HOSTS = new Set([
    "localhost", "127.0.0.1", "[::1]",
    ...(process.env.ALLOWED_HOSTS ?? "").split(",").map((s) => s.trim().toLowerCase()).filter(Boolean),
]);
app.use("/api", (req, res, next) => {
    const host = (req.headers.host ?? "").toLowerCase().replace(/:\d+$/, "");
    if (ALLOWED_HOSTS.has(host))
        return next();
    res.status(403).json({ error: { message: `Host "${host}" is not allowed. Add it to ALLOWED_HOSTS.` } });
});
// Prompts can carry attachments (base64), so allow larger bodies there.
app.use("/api/agent/prompt", express.json({ limit: "40mb" }));
// Playground vision turns carry images inline as base64 data URLs (4 x 5 MB max in the UI).
app.use("/api/chat", express.json({ limit: "32mb" }));
// Saved Playground sessions carry the same images, sealed into the body.
app.use("/api/playground", express.json({ limit: "40mb" }));
app.use("/api/render", express.json({ limit: "4mb" })); // a .drawio file; specs are capped in render.ts
app.use(express.json({ limit: "4mb" }));
// Rate limits before anything else under /api, sign-in included (see ratelimit.ts).
app.use("/api", apiLimiter);
mountAuth(app, ALLOWED_HOSTS);
// Any authenticated write counts as activity for the vault's auto-lock (reads
// don't, so the sidebar's status polling can't keep it open).
app.use("/api", (req, _res, next) => {
    if (req.method !== "GET")
        vault.touch();
    next();
});
/** An error (or anything) as a single log line, newlines escaped. */
const oneLine = (e) => String(e instanceof Error ? e.stack ?? e.message : e).replace(/\r/g, "").replace(/\n/g, " | ");
const sendError = (res, e) => {
    if (e instanceof SCXError) {
        // The provider rejecting our key is a configuration problem here, not the
        // browser's session: report it as an upstream failure with a pointer.
        if (e.status === 401 || e.status === 403) {
            return res.status(502).json({ error: { message: `SCX rejected the API key (${e.status}: ${e.message}). Check the SCX_API key in the vault.`, type: e.type } });
        }
        return res.status(e.status).json({ error: { message: e.message, type: e.type } });
    }
    const status = e?.status;
    if (status)
        return res.status(status).json({ error: { message: e.message } });
    // One line: an error message can carry request input, and a newline in it would forge log lines.
    console.error("[server error]", oneLine(e));
    return res.status(500).json({ error: { message: String(e?.message ?? e) } });
};
app.get("/api/health", (_req, res) => res.json({ ok: true, version: VERSION, baseUrl: PROVIDERS.scx.baseUrl }));
// --- Saved Playground sessions (see playground-store.ts) ---------------------
// Chats and canvases, sealed with the vault key into the runner-only data volume.
app.get("/api/playground/sessions/:kind", (req, res) => {
    try {
        res.json({ sessions: playground.list(req.params.kind) });
    }
    catch (e) {
        sendError(res, e);
    }
});
app.get("/api/playground/sessions/:kind/:id", (req, res) => {
    try {
        res.json(playground.get(req.params.kind, req.params.id));
    }
    catch (e) {
        sendError(res, e);
    }
});
app.put("/api/playground/sessions/:kind/:id", (req, res) => {
    try {
        const { title, body } = req.body ?? {};
        res.json(playground.put(req.params.kind, req.params.id, String(title ?? ""), body));
    }
    catch (e) {
        sendError(res, e);
    }
});
app.delete("/api/playground/sessions/:kind/:id", (req, res) => {
    try {
        playground.remove(req.params.kind, req.params.id);
        res.json({ ok: true });
    }
    catch (e) {
        sendError(res, e);
    }
});
app.delete("/api/playground/sessions/:kind", (req, res) => {
    try {
        res.json({ deleted: playground.removeAll(req.params.kind) });
    }
    catch (e) {
        sendError(res, e);
    }
});
// --- Key vault (see shared/vault.d.ts) --------------------------------------
// The browser does the key derivation and wrapping; these routes only store
// ciphertext, accept an unseal key into memory, and manage sealed items.
app.get("/api/vault", (_req, res) => res.json(vault.status(keySource("scx"))));
app.post("/api/vault/init", (req, res) => {
    try {
        const { doc, dek } = req.body ?? {};
        if (!doc || typeof dek !== "string")
            return res.status(400).json({ error: { message: "doc and dek required" } });
        vault.initialise(doc, dek);
        // Creating the vault turns sign-in on; the browser that created it is signed in.
        issueSession(req, res);
        res.json(vault.status(keySource("scx")));
    }
    catch (e) {
        sendError(res, e);
    }
});
app.post("/api/vault/unseal", (req, res) => {
    try {
        if (typeof req.body?.dek !== "string")
            return res.status(400).json({ error: { message: "dek required" } });
        vault.unseal(req.body?.dek);
        res.json(vault.status(keySource("scx")));
    }
    catch (e) {
        sendError(res, e);
    }
});
app.post("/api/vault/seal", (_req, res) => {
    vault.sealVault();
    res.json(vault.status(keySource("scx")));
});
app.put("/api/vault/items/:name", (req, res) => {
    try {
        if (typeof req.body?.value !== "string")
            return res.status(400).json({ error: { message: "value required" } });
        vault.setItem(req.params.name, req.body?.value);
        res.json(vault.status(keySource("scx")));
    }
    catch (e) {
        sendError(res, e);
    }
});
app.delete("/api/vault/items/:name", (req, res) => {
    try {
        vault.deleteItem(req.params.name);
        res.json(vault.status(keySource("scx")));
    }
    catch (e) {
        sendError(res, e);
    }
});
/** Enrol another passkey. The browser must prove it holds the current key (it wrapped it for the new method). */
app.post("/api/vault/methods", (req, res) => {
    try {
        const { method, dek } = req.body ?? {};
        if (!method || typeof dek !== "string")
            return res.status(400).json({ error: { message: "method and dek required" } });
        vault.addMethod(method, dek);
        res.json(vault.status(keySource("scx")));
    }
    catch (e) {
        sendError(res, e);
    }
});
app.delete("/api/vault/methods/:id", (req, res) => {
    try {
        vault.removeMethod(req.params.id);
        res.json(vault.status(keySource("scx")));
    }
    catch (e) {
        sendError(res, e);
    }
});
/**
 * Delete the vault, to recreate it with new factors. Needs the current key as
 * proof, so it is a rotation tool for the owner, not a way around the lock.
 * Lost every factor? Reset from the server instead: `npm run vault:reset`.
 */
app.delete("/api/vault", (req, res) => {
    try {
        if (typeof req.body?.dek !== "string")
            return res.status(400).json({ error: { message: "dek required" } });
        vault.destroy(req.body?.dek);
        res.json(vault.status(keySource("scx")));
    }
    catch (e) {
        sendError(res, e);
    }
});
/** List models (with capabilities + pricing) for the playground's model picker. */
// --- GitHub, read-only (see shared/github.d.ts) ------------------------------
app.get("/api/github", async (_req, res) => {
    try {
        res.json(await github.status());
    }
    catch (e) {
        sendError(res, e);
    }
});
app.post("/api/github/connect/start", async (_req, res) => {
    try {
        res.json(await github.connectStart());
    }
    catch (e) {
        sendError(res, e);
    }
});
app.post("/api/github/connect/poll", async (req, res) => {
    try {
        const r = await github.connectPoll(req.body?.id);
        if (r.status === "connected")
            audit("github.connected", { login: r.login, storage: r.storage });
        res.json(r);
    }
    catch (e) {
        sendError(res, e);
    }
});
app.delete("/api/github/connect", (_req, res) => {
    try {
        github.disconnect();
        audit("github.disconnected");
        res.json({ ok: true });
    }
    catch (e) {
        sendError(res, e);
    }
});
app.get("/api/github/repos", async (_req, res) => {
    try {
